/** Pure replay state; events have already been expanded by the Python validator. */
export function stateAt(events, step) {
  const state = new Map();
  for (const event of events.slice(0, Math.max(0, Math.min(step, events.length)))) {
    if (event.action === 'place') state.set(event.placement.piece_id, event.placement);
    else state.delete(event.placement.piece_id);
  }
  return state;
}

export function coverage(state) {
  return [...state.values()].reduce((count, piece) => count + piece.cells.length, 0);
}

export class Playback {
  constructor(events, update, scheduler = globalThis) {
    this.events = events;
    this.update = update;
    this.scheduler = scheduler;
    this.step = 0;
    this.delay = 700;
    this.timer = null;
  }
  pause() {
    if (this.timer !== null) this.scheduler.clearTimeout(this.timer);
    this.timer = null;
  }
  seek(step) {
    this.pause();
    this.step = Math.max(0, Math.min(Number(step), this.events.length));
    this.update(this.step, false);
  }
  play() {
    this.pause();
    if (this.step >= this.events.length) return;
    this.timer = this.scheduler.setTimeout(() => {
      this.timer = null;
      this.step++;
      this.update(this.step, true);
      this.play();
    }, this.delay);
  }
  setSpeed(delay) {
    const active = this.timer !== null;
    this.delay = delay;
    if (active) this.play();
  }
  dispose() { this.pause(); }
}
